local a=peripheral.find("inventory")if not a or not peripheral.hasType(a,"inventory")then return nil end;local b=a;b.itemTypes={}b.index={}b.index.defaultMaxCount=64;b.index.isIndexed=false;b.index.latestLog={}function b.index.index()b.index.isIndexed=false;table.insert(b.index.latestLog,"starting indexing ...")local c=b.list()for d,e in pairs(c)do if e and not b.itemTypes[e.name]then local f,g=pcall(b.getItemDetail,d)if f and g then table.insert(b.itemTypes,{g.name,g.displayName,g.maxCount})end;sleep(0)end;table.insert(b.index.latestLog,"indexing: "..d/#c*100 .."%")end;b.index.isIndexed=true;table.insert(b.index.latestLog,"indexing completed.")end;print("[storage] indexing complete.")function b.count()local h=0;for d,e in pairs(b.list())do if e~=nil and e.count~=nil then h=h+e.count end end;return h end;function b.maxCount()local h=(b.size()-#b.list())*64;for d,e in pairs(b.list())do if e~=nil then if b.itemTypes[e.name]then h=h+b.itemTypes[e.name]else h=h+(b.getItemDetail(d).maxCount or b.index.defaultMaxCount)end end end;return h end;function b.percentage()return math.floor(b.count()/b.maxCount()*100)end;return b
